      "type": "tenant_break_option",
      "quote": "Party B may sublets the Premises, transfers the leasing right of the Premises or exchanges with a third party their respective leased Premises without permission."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B fails to pay the rent for 1 month."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event that Party B early surrenders the lease other than in accordance with the provisions herein during the tenancy, the Deposit paid by Party B shall not be returned."
